 {name: 'Paradise',         lon: -115.1469, lat: 36.0970, zoom: 13},
 {name: 'Enterprise',       lon: -115.2200, lat: 36.0265, zoom: 13},
 {name: 'Spring Valley',    lon: -115.2450, lat: 36.1070, zoom: 13},
